// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"saccharomyces-boulardii":{"wirkmechanismus":"Unterstützt die Darmflora und hilft dem Darm, sich von Durchfall zu erholen. Die lebende Hefe übersteht die Magenpassage, siedelt sich vorübergehend im Darm an und wird nach dem Absetzen innert 2 bis 5 Tagen wieder ausgeschieden. Sie hemmt das Wachstum krankmachender Keime, baut bakterielle Giftstoffe ab (z. B. die Toxine von Clostridioides difficile) und stärkt die Darmschleimhaut sowie die örtliche Immunabwehr (sekretorisches IgA). Sie wird nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Hautausschlag, Quincke-Ödem)","Fungämie (Hefe im Blut) bei Patienten mit zentralem Venenkatheter, schwer Kranken oder Immungeschwächten"],"unbekannt":["Anaphylaxie (allergischer Schock)","Blähungen","Verstopfung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Keine ausreichenden Erfahrungen; nur nach Rücksprache anwenden.","hinweise":["Nicht zusammen mit sehr heissen (über 50 °C) oder eisgekühlten Speisen und Getränken oder mit Alkohol einnehmen – die Hefe ist lebend.","Bei Durchfall genügend Flüssigkeit und Salze ersetzen, besonders bei Kindern und älteren Menschen.","Bei Antibiotika-Behandlung kann die Hefe gleichzeitig eingenommen werden; Pilzmittel heben die Wirkung dagegen auf."],"darreichung":["Kapseln","Pulver zum Einnehmen (Beutel)"]},"sacubitril-valsartan":{"wirkmechanismus":"Entlastet das geschwächte Herz, indem es körpereigene Schutzhormone verstärkt und gleichzeitig das gefässverengende Angiotensin II blockiert. Sacubitril ist ein Prodrug; sein Wirkmetabolit Sacubitrilat (LBQ657) hemmt das Enzym Neprilysin, das natriuretische Peptide (ANP, BNP) abbaut. Diese Peptide erweitern die Gefässe, fördern die Ausscheidung von Salz und Wasser und wirken krankhaften Umbauvorgängen am Herzmuskel entgegen. Valsartan blockiert den Angiotensin-II-Rezeptor Typ 1 (AT1) und verhindert so die schädliche Aktivierung des Renin-Angiotensin-Aldosteron-Systems. Weil Neprilysin auch Bradykinin abbaut, darf die Kombination nicht mit ACE-Hemmern gegeben werden (Angioödem-Gefahr).","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium)","Hypotonie (tiefer Blutdruck)","Nierenfunktionsstörung"],"haeufig":["Schwindel, Kopfschmerzen, Synkope (kurze Ohnmacht), Vertigo (Drehschwindel)","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Nierenversagen, auch akut","Hypokaliämie (tiefes Kalium), Hypoglykämie (Unterzuckerung)","Anämie (Blutarmut)","Husten","Durchfall, Übelkeit, Gastritis (Magenschleimhautentzündung)","Müdigkeit, Asthenie (Schwäche)"],"gelegentlich":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Überempfindlichkeitsreaktionen","Juckreiz, Hautausschlag","Schwindel beim Lagewechsel"],"selten":["Halluzinationen","Schlafstörungen"],"sehrSelten":["Paranoia (Verfolgungswahn)"],"unbekannt":["Angioödem des Darms (Bauchschmerzen, Übelkeit, Erbrechen, Durchfall)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung des Ungeborenen wie bei allen RAAS-Hemmern). Bei festgestellter Schwangerschaft sofort ärztlich umstellen.","stillzeit":"Nicht anwenden – Übergang in die Muttermilch und Risiken für den Säugling können nicht ausgeschlossen werden.","hinweise":["Beim Wechsel von einem ACE-Hemmer diesen mindestens 36 Stunden vorher absetzen; keinen zusätzlichen ACE-Hemmer oder anderes Sartan einnehmen.","Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen sofort absetzen und Notfallhilfe holen.","Blutdruck, Kalium und Nierenwerte regelmässig kontrollieren; als Herzschwäche-Laborwert eignet sich NT-proBNP, nicht BNP (BNP steigt unter der Behandlung an).","Zweimal täglich einnehmen, mit oder ohne Essen; zu Beginn Schwindel möglich (Vorsicht beim Autofahren)."],"darreichung":["Filmtabletten"]},"saegepalmenfruechte-extrakt":{"wirkmechanismus":"Pflanzlicher Extrakt, der die Beschwerden beim Wasserlassen lindert, ohne die Prostata zu verkleinern. Der Wirkmechanismus des fettlöslichen Extrakts aus Sägepalmenfrüchten ist nicht vollständig geklärt. In Laborversuchen hemmt er unter anderem die 5-Alpha-Reduktase und die Bindung von Androgenen und wirkt entzündungs- und wachstumshemmend auf Prostatazellen.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Magenschmerzen)","Überempfindlichkeitsreaktionen (z. B. Hautausschlag)"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Mit oder nach einer Mahlzeit einnehmen; das vermindert Magenbeschwerden.","Die Wirkung setzt erst nach einigen Wochen ein; die Prostata wird nicht verkleinert.","Regelmässige ärztliche Kontrollen der Prostata sind auch während der Behandlung nötig."],"darreichung":["Kapseln"]},"salbutamol":{"wirkmechanismus":"Erweitert innert Minuten verengte Bronchien und erleichtert das Atmen. Salbutamol stimuliert selektiv Beta-2-Rezeptoren der Bronchialmuskulatur; über einen Anstieg von cAMP erschlafft die glatte Muskulatur. Die Wirkung beginnt nach wenigen Minuten und hält etwa 4–6 Stunden an. Auf die Entzündung der Atemwege bei Asthma hat es keinen Einfluss.","nebenwirkungen":{"haeufig":["Zittern (Tremor)","Kopfschmerzen","Beschleunigter Puls (Tachykardie)"],"gelegentlich":["Herzklopfen","Reizung von Mund und Rachen","Muskelkrämpfe"],"selten":["Hypokaliämie (Kaliummangel)","Erweiterung der Blutgefässe mit Hautrötung"],"sehrSelten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Blutdruckabfall, Kollaps)","Paradoxer Bronchospasmus","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Hyperaktivität"],"unbekannt":["Myokardischämie (Durchblutungsstörung des Herzmuskels)","Laktatazidose bei sehr hohen Dosen (z. B. Vernebler im Spital)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Salbutamol geht wahrscheinlich in die Muttermilch über; Anwendung nach ärztlicher Abwägung.","hinweise":["Dosieraerosol vor Gebrauch schütteln; mit Inhalierhilfe (Spacer) gelangt mehr Wirkstoff in die Lunge – Inhalationstechnik in der Apotheke zeigen lassen.","Wird das Spray häufiger als gewohnt gebraucht, ist das Asthma nicht ausreichend kontrolliert – ärztlich abklären lassen.","Bei Asthma ersetzt Salbutamol keine entzündungshemmende Basistherapie mit inhalativem Kortison."],"darreichung":["Dosieraerosol","Pulverinhalator","Inhalationslösung (Vernebler)"]},"salmeterol":{"wirkmechanismus":"Hält die Bronchien etwa 12 Stunden lang offen. Salmeterol ist ein selektiver Beta-2-Agonist mit einer langen, fettlöslichen Seitenkette, die nahe am Rezeptor verankert bleibt und ihn wiederholt aktiviert; über einen Anstieg von cAMP erschlafft die Bronchialmuskulatur. Die Wirkung setzt erst nach 10–20 Minuten ein, deshalb ist es nicht für akute Atemnot geeignet. Gegen die Entzündung der Atemwege wirkt es nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Zittern (Tremor)","Herzklopfen","Muskelkrämpfe"],"gelegentlich":["Hautausschlag","Nervosität","Beschleunigter Puls (Tachykardie)"],"selten":["Hypokaliämie (Kaliummangel)","Schlaflosigkeit"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem","Hyperglykämie (erhöhter Blutzucker)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Paradoxer Bronchospasmus","Reizung von Mund und Rachen","Gelenkschmerzen, unspezifische Brustschmerzen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nicht bei akuter Atemnot verwenden – dafür immer ein rasch wirksames Spray (z. B. Salbutamol) mitführen.","Bei Asthma immer zusammen mit einem inhalativen Kortison anwenden, am einfachsten als Kombinationspräparat.","Regelmässig zweimal täglich anwenden, auch wenn keine Beschwerden bestehen."],"darreichung":["Dosieraerosol","Pulverinhalator"]},"salmeterol-fluticason":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer lang anhaltenden bronchienerweiternden Wirkung. Fluticasonpropionat ist ein Glukokortikoid, das in der Bronchialschleimhaut die Bildung von Entzündungsstoffen und die Überempfindlichkeit der Atemwege vermindert. Salmeterol stimuliert Beta-2-Rezeptoren der Bronchialmuskulatur und hält die Atemwege etwa 12 Stunden offen. Gemeinsam senken sie die Zahl der Asthmaanfälle bzw. COPD-Verschlechterungen.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasen-Rachen-Entzündung (Nasopharyngitis)"],"haeufig":["Pilzinfektion in Mund und Rachen (Soor)","Heiserkeit, Rachenreizung","Lungenentzündung (bei COPD)","Bronchitis, Nebenhöhlenentzündung","Hypokaliämie (Kaliummangel)","Muskelkrämpfe, Gelenk- und Muskelschmerzen","Prellungen, Knochenbrüche nach Unfällen"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut, Atemnot","Katarakt (Grauer Star)","Hyperglykämie (erhöhter Blutzucker)","Angst, Schlafstörungen","Zittern, Herzklopfen, beschleunigter Puls","Vorhofflimmern, Angina pectoris"],"selten":["Anaphylaxie, Angioödem, paradoxer Bronchospasmus","Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung bei Kindern, verminderte Knochendichte","Glaukom (Grüner Star)","Verhaltensänderungen (Hyperaktivität, Reizbarkeit), vor allem bei Kindern","Herzrhythmusstörungen (supraventrikuläre Tachykardie, Extrasystolen)","Pilzinfektion der Speiseröhre"],"unbekannt":["Depression, Aggressivität","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung und in der niedrigsten wirksamen Dosis; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Regelmässig anwenden, auch ohne Beschwerden; für akute Atemnot ein rasch wirkendes Spray mitführen.","Nicht abrupt absetzen; Dosisänderungen nur nach ärztlicher Rücksprache.","Eine Ritonavir- oder Cobicistat-haltige HIV-Therapie vor Behandlungsbeginn ärztlich angeben."],"darreichung":["Pulverinhalator","Dosieraerosol"]},"sapropterin":{"wirkmechanismus":"Hilft dem geschwächten Enzym, das die Aminosäure Phenylalanin abbaut, wieder besser zu arbeiten. Sapropterin ist eine synthetische Form von Tetrahydrobiopterin (BH4), dem natürlichen Cofaktor der Phenylalaninhydroxylase, die Phenylalanin in Tyrosin umwandelt. Bei Phenylketonurie mit Restaktivität des Enzyms steigert BH4 dessen Aktivität und Stabilität; bei BH4-Mangel ersetzt es den fehlenden Cofaktor. Nicht alle Betroffenen sprechen an, deshalb wird das Ansprechen zu Beginn getestet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schnupfen (Rhinorrhö)"],"haeufig":["Halsschmerzen, verstopfte Nase, Husten","Durchfall, Erbrechen, Übelkeit","Bauchschmerzen, Verdauungsbeschwerden","Zu tiefer Phenylalaninspiegel (Hypophenylalaninämie)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Hautausschlag","Gastritis und Ösophagitis (Magen- und Speiseröhrenentzündung)"]},"schwangerschaft":"Nur anwenden, wenn eine strenge Diät den Phenylalaninspiegel nicht ausreichend senkt; ein zu hoher Phenylalaninspiegel der Mutter schädigt das Ungeborene.","stillzeit":"Nicht anwenden.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen, möglichst immer zur gleichen Tageszeit; Tabletten bzw. Pulver in Wasser oder Apfelsaft auflösen.","Die phenylalaninarme Diät nur nach Rücksprache mit dem Stoffwechselzentrum ändern.","Phenylalanin- und Tyrosinspiegel im Blut regelmässig kontrollieren lassen."],"darreichung":["Tabletten zur Herstellung einer Lösung zum Einnehmen","Pulver zur Herstellung einer Lösung zum Einnehmen"]},"saxagliptin":{"wirkmechanismus":"Verstärkt die körpereigene Blutzuckerregulation nach den Mahlzeiten. Saxagliptin hemmt das Enzym Dipeptidylpeptidase-4 (DPP-4), das die Darmhormone GLP-1 und GIP (Inkretine) rasch abbaut. Die höheren Inkretinspiegel steigern blutzuckerabhängig die Insulinfreisetzung und hemmen die Glucagonausschüttung. Weil die Wirkung an erhöhte Blutzuckerwerte gebunden ist, verursacht Saxagliptin allein selten Unterzuckerungen. Es wird über CYP3A4/5 zu einem ebenfalls wirksamen Metaboliten abgebaut.","nebenwirkungen":{"haeufig":["Infektionen der oberen Atemwege, Sinusitis (Nasennebenhöhlenentzündung)","Harnwegsinfekte","Gastroenteritis (Magen-Darm-Infekt)","Kopfschmerzen","Erbrechen","Hypoglykämie (Unterzuckerung) in Kombination mit Sulfonylharnstoffen oder Insulin"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht)"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"],"unbekannt":["Bullöses Pemphigoid (blasenbildende Hauterkrankung)","Obstipation (Verstopfung)","Gelenkschmerzen"]},"schwangerschaft":"Nicht anwenden, da keine ausreichenden Erfahrungen vorliegen; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht anwenden; es ist nicht bekannt, ob Saxagliptin in die Muttermilch übergeht.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen (evtl. mit Ausstrahlung in den Rücken) sofort ärztlich abklären lassen.","Blasen auf der Haut ärztlich melden.","Kombinationspräparate mit Metformin (Kombiglyze XR) oder Dapagliflozin (Qtern) haben zusätzlich die Gegenanzeigen dieser Wirkstoffe."],"darreichung":["Filmtabletten","Retardtabletten (Kombination mit Metformin)"]},"scopolamin":{"wirkmechanismus":"Dämpft die Weiterleitung von Signalen aus dem Gleichgewichtsorgan an das Brechzentrum und beugt so der Reisekrankheit vor. Scopolamin blockiert als tertiäres Amin Muskarinrezeptoren im Gehirn, unter anderem in den Vestibulariskernen und im Brechzentrum. Das Pflaster gibt den Wirkstoff gleichmässig über rund 72 Stunden durch die Haut ab, was die Nebenwirkungen im Vergleich zu Tabletten verringert. Wie Atropin hemmt es zudem Speichel- und Schweissbildung und erweitert die Pupille.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Schläfrigkeit (Somnolenz)","Verschwommenes Sehen, Akkommodationsstörungen, Pupillenerweiterung (auch einseitig nach Berühren des Auges mit Pflasterresten)","Lidreizung","Hautreizung an der Klebestelle"],"selten":["Gedächtnis- und Konzentrationsstörungen, Unruhe, Desorientierung, Verwirrtheit, Halluzinationen","Glaukomanfall (Anstieg des Augeninnendrucks)","Störungen beim Wasserlassen, Harnverhalt"],"sehrSelten":["Ausgedehnter Hautausschlag"],"unbekannt":["Entzugsbeschwerden nach Entfernen des Pflasters nach mehrtägiger Anwendung (Schwindel, Übelkeit, Erbrechen, Kopfschmerzen, Gleichgewichtsstörungen)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; in der Schwangerschaft nur nach ärztlicher Abwägung anwenden.","stillzeit":"Scopolamin geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Pflaster am Vorabend oder spätestens 5–6 Stunden vor Reiseantritt auf saubere, unbehaarte Haut hinter dem Ohr kleben; wirkt bis zu 72 Stunden.","Nach dem Aufkleben oder Entfernen gründlich die Hände waschen: Wirkstoff in den Augen erweitert die Pupille und stört das Sehen.","Kann müde machen und das Sehen beeinträchtigen: nicht selbst Auto fahren oder Maschinen bedienen; Alkohol meiden.","Vor einer MRI-Untersuchung entfernen (Pflaster enthält Metall)."],"darreichung":["Transdermales Pflaster"]},"sebelipase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das Cholesterinester und Triglyceride in den Zellen abbaut. Sebelipase alfa ist eine gentechnisch im Eiklar transgener Hühner hergestellte menschliche lysosomale saure Lipase. Sie wird über Mannose- und Mannose-6-Phosphat-Rezeptoren vor allem von Leberzellen und Makrophagen aufgenommen und spaltet in den Lysosomen Cholesterinester und Triglyceride. Dadurch sinken Leberfett, Leberwerte und LDL-Cholesterin; bei schwer betroffenen Säuglingen verbessert sich das Überleben.","nebenwirkungen":{"sehrHaeufig":["Bei Säuglingen: infusionsbedingte Reaktionen mit Fieber, Schüttelfrost, Unruhe, Herzrasen, Atembeschwerden, Ausschlag, Nesselsucht oder Erbrechen"],"haeufig":["Überempfindlichkeitsreaktionen, auch Anaphylaxie und Kehlkopfschwellung","Schwindel","Herzrasen","Atemnot","Durchfall, Bauchschmerzen, Blähbauch, Übelkeit","Nesselsucht, Ausschlag, Juckreiz","Schüttelfrost, Fieber, Brustbeschwerden, Müdigkeit"]},"schwangerschaft":"Keine Erfahrungen. Vorsichtshalber möglichst nicht anwenden; nur nach strenger ärztlicher Abwägung.","stillzeit":"Keine Daten zum Übergang in die Muttermilch. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird als Infusion in eine Vene gegeben, bei Säuglingen wöchentlich, sonst meist alle 2 Wochen.","Eine Allergie gegen Ei vor Behandlungsbeginn unbedingt angeben.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"secukinumab":{"wirkmechanismus":"Bremst Entzündungen in Haut, Gelenken und Wirbelsäule. Secukinumab ist ein humaner monoklonaler IgG1-Antikörper, der den Botenstoff Interleukin-17A bindet und neutralisiert. IL-17A treibt bei Psoriasis und Spondyloarthritis die Entzündung und die übermässige Vermehrung von Hautzellen an; seine Blockade lässt Hautplaques und Gelenkentzündung zurückgehen.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (Erkältung, Nasen-Rachen-Entzündung)"],"haeufig":["Lippenherpes (oraler Herpes simplex)","Fusspilz (Tinea pedis)","Kopfschmerzen","Schnupfen","Durchfall, Übelkeit","Müdigkeit"],"gelegentlich":["Orale Candidose (Mundsoor), Infektionen der unteren Atemwege, Gehörgangsentzündung","Neutropenie (Mangel an neutrophilen Granulozyten)","Konjunktivitis (Bindehautentzündung)","Chronisch entzündliche Darmerkrankung (neu oder verschlechtert)","Nesselsucht, dyshidrotisches Ekzem"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Exfoliative Dermatitis (grossflächige Hautabschälung)","Vaskulitis (Gefässentzündung)"],"unbekannt":["Pilzinfektionen von Haut und Schleimhäuten, auch der Speiseröhre","Pyoderma gangraenosum (geschwürige Hauterkrankung)"]},"schwangerschaft":"Vorsichtshalber während der Schwangerschaft vermeiden; Frauen im gebärfähigen Alter verhüten während und bis 20 Wochen nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist wahrscheinlich; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Vor Beginn auf Tuberkulose testen und den Impfstatus vervollständigen lassen.","Bei anhaltendem Durchfall mit Blut oder Bauchkrämpfen ärztlich abklären lassen (entzündliche Darmerkrankung).","Im Kühlschrank lagern, nicht schütteln."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen)"]},"selen":{"wirkmechanismus":"Selen ist ein Spurenelement, das als Bestandteil von Enzymen die Zellen vor oxidativen Schäden schützt und für den Schilddrüsenhormon-Stoffwechsel gebraucht wird. Natriumselenit wird im Körper in die Aminosäure Selenocystein eingebaut, das aktive Zentrum der Selenoproteine, z. B. der Glutathionperoxidasen, Thioredoxinreduktasen und Deiodasen. Die Spanne zwischen notwendiger und giftiger Dosis ist relativ eng.","nebenwirkungen":{"unbekannt":["Bei Überdosierung (Selenose): knoblauchartiger Atemgeruch, Müdigkeit, Übelkeit, Durchfall, Bauchschmerzen","Bei chronischer Überdosierung: Haarausfall, brüchige Nägel, Hautausschlag, Nervenstörungen"]},"schwangerschaft":"Bei nachgewiesenem Mangel in angemessener Dosis nach ärztlicher Abwägung möglich; eine Überdosierung ist zu vermeiden.","stillzeit":"Selen geht in die Muttermilch über; nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung.","hinweise":["Nicht gleichzeitig mit Vitamin C einnehmen.","Ohne ärztliche Rücksprache keine zusätzlichen selenhaltigen Nahrungsergänzungsmittel einnehmen."],"darreichung":["Lösung zum Einnehmen","Injektionslösung"]},"semaglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1: Semaglutid steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und dämpft über das Gehirn Appetit und Hungergefühl. Dank einer Fettsäure-Seitenkette bindet es stark an Albumin und hat eine Halbwertszeit von etwa einer Woche, deshalb wird es einmal wöchentlich gespritzt. In der Tablette (Rybelsus) schützt der Hilfsstoff SNAC den Wirkstoff im Magen und ermöglicht die Aufnahme über die Magenschleimhaut – daher die strengen Einnahmeregeln. In grossen Studien senkte Semaglutid bei Typ-2-Diabetes bzw. bei Übergewicht mit bestehender Herz-Kreislauf-Erkrankung das Risiko schwerer Herz-Kreislauf-Ereignisse.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen, Verstopfung, Bauchschmerzen (unter Wegovy sehr häufig, unter Ozempic häufig)","Kopfschmerzen und Müdigkeit (unter Wegovy)","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoff"],"haeufig":["Appetitminderung","Schwindel","Verdauungsbeschwerden, Gastritis, Reflux, Aufstossen, Blähungen","Gallensteine (Cholelithiasis)","Komplikationen einer diabetischen Retinopathie (Netzhautschaden) bei Typ-2-Diabetes","Haarausfall (unter Wegovy)","Erhöhte Lipase- und Amylasewerte"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhter Puls","Verzögerte Magenentleerung","Geschmacksstörung","Überempfindlichkeitsreaktionen","Reaktionen an der Injektionsstelle","Blutdruckabfall, Schwindel beim Aufstehen (unter Wegovy)"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["NAION (nicht-arteriitische anteriore ischämische Optikusneuropathie): Durchblutungsstörung des Sehnervs mit plötzlichem Sehverlust"],"unbekannt":["Darmverschluss (Ileus)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"]},"schwangerschaft":"Nicht anwenden: Tierversuche zeigten Fruchtschädigung. Wegen der langen Wirkdauer mindestens 2 Monate vor einer geplanten Schwangerschaft absetzen; bei Diabetes wird Insulin eingesetzt.","stillzeit":"Nicht anwenden: Semaglutid geht bei Tieren in die Milch über; bei Rybelsus gelangt zudem der Hilfsstoff SNAC in die Muttermilch.","hinweise":["Spritze (Ozempic, Wegovy) einmal pro Woche am gleichen Wochentag, unabhängig vom Essen; die Dosis wird zur besseren Verträglichkeit schrittweise gesteigert.","Rybelsus morgens nüchtern mit höchstens einem halben Glas Wasser (bis 120 ml) ganz schlucken und danach mindestens 30 Minuten nichts essen, trinken oder andere Tabletten einnehmen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen; bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben; bei plötzlicher Sehverschlechterung sofort ärztlich abklären."],"darreichung":["Injektionslösung im Fertigpen","Tabletten (Rybelsus)"]},"sennoside":{"wirkmechanismus":"Regt die Dickdarmbewegung an und hält Wasser im Darm zurück, wodurch der Stuhl weicher wird. Die Sennoside sind Anthranoid-Glykoside, die unverändert bis in den Dickdarm gelangen. Dort spalten Darmbakterien sie zum wirksamen Rheinanthron, das die Peristaltik beschleunigt, die Rückaufnahme von Wasser und Salzen hemmt und deren Ausscheidung in den Darm fördert. Die Wirkung setzt nach etwa 8–12 Stunden ein.","nebenwirkungen":{"unbekannt":["Bauchkrämpfe und Bauchschmerzen, besonders bei Reizdarm","Durchfall mit wässrigen Stühlen","Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Hautausschlag)","Harmlose gelbe oder rotbraune Verfärbung des Urins","Bei längerer Anwendung: Störungen des Wasser- und Salzhaushalts, besonders Kaliummangel","Bei längerer Anwendung: Eiweiss und Blut im Urin","Bei längerer Anwendung: harmlose Dunkelfärbung der Darmschleimhaut (Pseudomelanosis coli)"]},"schwangerschaft":"Wegen Hinweisen auf erbgutverändernde Wirkungen einzelner Anthranoide im Labor in der Schwangerschaft nicht empfohlen; zuerst Ernährungsmassnahmen und Quellstoffe versuchen.","stillzeit":"Geringe Mengen wirksamer Abbauprodukte gehen in die Muttermilch über; Anwendung nicht empfohlen.","hinweise":["Nicht länger als 1–2 Wochen ohne ärztlichen Rat anwenden.","Am besten abends einnehmen; die Wirkung tritt nach 8–12 Stunden ein. Ausreichend trinken.","Eine Verfärbung des Urins ist harmlos."],"darreichung":["Tabletten","Granulat","Tee"]},"sertralin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Angst und Zwänge, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Sertralin hemmt selektiv den Serotonin-Transporter und damit die Wiederaufnahme von Serotonin in die Nervenzelle; auf die Wiederaufnahme von Noradrenalin und Dopamin wirkt es nur schwach. Die Halbwertszeit beträgt etwa 26 Stunden; die volle Wirkung entwickelt sich über 2–4 Wochen.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit, Schläfrigkeit","Schwindel, Kopfschmerzen","Durchfall, Übelkeit, Mundtrockenheit","Ejakulationsstörungen","Müdigkeit"],"haeufig":["Angst, Unruhe, Nervosität, Albträume, Zähneknirschen","Verminderte Libido, Erektionsstörungen","Zittern, Kribbeln, erhöhte Muskelspannung, Konzentrations- und Geschmacksstörungen","Sehstörungen, Ohrgeräusche (Tinnitus)","Herzklopfen, Hitzewallungen, Gähnen","Bauchschmerzen, Erbrechen, Verstopfung, Verdauungsbeschwerden, Blähungen","Vermehrtes Schwitzen, Hautausschlag","Rücken-, Gelenk- und Muskelschmerzen, Brustschmerzen"],"gelegentlich":["Halluzinationen, Aggressivität, gehobene Stimmung","Migräne, Ohnmacht (Synkope)","Herzrasen, Bluthochdruck","Nasenbluten, Atemnot","Schluckbeschwerden","Nesselsucht, Juckreiz, Haarausfall, Hautblutungen (Purpura)","Harninkontinenz"],"selten":["Hyponatriämie (Natriummangel), inadäquate ADH-Sekretion (SIADH)","Krampfanfälle, Bewegungsstörungen","Serotoninsyndrom","QT-Verlängerung, Torsade de pointes","Schwere Leberfunktionsstörungen","Angioödem, schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Magen-Darm-Blutungen","Priapismus (Dauererektion), Milchfluss (Galaktorrhö)"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Mikroskopische Kolitis (chronischer wässriger Durchfall)","Nachblutungen nach der Geburt","Erhöhtes Risiko für Knochenbrüche"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Daten aus vielen Schwangerschaften zeigen kein erhöhtes Fehlbildungsrisiko. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Sertralin geht nur in geringen Mengen in die Muttermilch über und ist im Blut gestillter Kinder meist nicht nachweisbar; eine Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Einmal täglich morgens oder abends einnehmen, unabhängig von den Mahlzeiten.","Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken zu Beginn sofort ärztlich melden.","Nicht abrupt absetzen, sondern schrittweise reduzieren (Absetzsymptome).","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol und Grapefruitsaft meiden."],"darreichung":["Filmtabletten"]},"setmelanotid":{"wirkmechanismus":"Ersetzt ein fehlendes Sättigungssignal im Gehirn und vermindert so den krankhaften Hunger. Setmelanotid ist ein Peptid, das den Melanocortin-4-Rezeptor (MC4R) im Hypothalamus aktiviert. Bei Gendefekten im Leptin-Melanocortin-Signalweg stellt es die Signalübertragung wieder her, senkt Hunger und Nahrungsaufnahme und fördert die Gewichtsabnahme. Da es auch den Melanocortin-1-Rezeptor der Pigmentzellen anregt, dunkelt die Haut häufig nach.","nebenwirkungen":{"sehrHaeufig":["Dunklere Hautpigmentierung (Hyperpigmentierung)","Reaktionen an der Einstichstelle (Rötung, Juckreiz, Schwellung, Schmerz)","Übelkeit","Erbrechen","Kopfschmerzen"],"haeufig":["Durchfall","Bauchschmerzen","Müdigkeit","Schwindel","Juckreiz"],"unbekannt":["Spontane Erektionen und andere Störungen der sexuellen Erregung","Neue oder veränderte Muttermale (Nävi)","Depression, Suizidgedanken"]},"schwangerschaft":"Keine ausreichenden Daten; aus Vorsicht nicht anwenden (eine Gewichtsabnahme ist in der Schwangerschaft unerwünscht). Bei Eintritt einer Schwangerschaft die Behandlung ärztlich überprüfen.","stillzeit":"Nicht bekannt, ob Setmelanotid in die Muttermilch übergeht; Nutzen und Risiko ärztlich abwägen.","hinweise":["Einmal täglich zu Beginn des Tages unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen; Einstichstelle wechseln.","Vor Beginn und während der Behandlung die Haut regelmässig auf Muttermale und Pigmentveränderungen untersuchen lassen.","Stimmungsveränderungen oder Suizidgedanken sofort ärztlich melden.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall."],"darreichung":["Injektionslösung zur Anwendung unter die Haut"]},"sevelamer":{"wirkmechanismus":"Bindet Phosphat aus der Nahrung im Darm, sodass weniger davon ins Blut gelangt. Sevelamer ist ein nicht resorbierbares, vernetztes Poly(allylamin)-Polymer, dessen im Darm protonierte Aminogruppen Phosphat über Ionen- und Wasserstoffbrücken binden. Es enthält weder Calcium noch Metalle. Zusätzlich bindet es Gallensäuren und senkt dadurch das LDL-Cholesterin.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Schmerzen im Oberbauch","Verstopfung"],"haeufig":["Durchfall","Verdauungsbeschwerden (Dyspepsie)","Blähungen","Bauchschmerzen"],"sehrSelten":["Überempfindlichkeitsreaktionen"],"unbekannt":["Darmverschluss (Ileus), Darmdurchbruch","Magen-Darm-Blutungen, Darmgeschwüre, Kolitis, Darmnekrose","Kristallablagerungen in der Darmschleimhaut","Juckreiz, Hautausschlag"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; Erfahrungen beim Menschen fehlen. Die Aufnahme von Vitaminen und Folsäure kann vermindert sein.","stillzeit":"Wird nicht ins Blut aufgenommen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Zu den Mahlzeiten einnehmen; Tabletten ganz schlucken, nicht zerkauen oder zerbrechen.","Andere Medikamente, deren Wirkung wichtig ist, mindestens 1 Stunde vor oder 3 Stunden nach Sevelamer einnehmen.","Phosphatarme Ernährung beibehalten; bei starker Verstopfung oder Bauchschmerzen ärztlich melden."],"darreichung":["Filmtabletten","Pulver zur Herstellung einer Suspension zum Einnehmen"]},"sevofluran":{"wirkmechanismus":"Versetzt beim Einatmen rasch in einen tiefen Schlaf, in dem Schmerzreize nicht mehr wahrgenommen werden. Sevofluran ist ein halogenierter Ether, der die Erregungsübertragung im Zentralnervensystem dämpft, unter anderem durch Verstärkung hemmender GABA-A- und Glycin-Rezeptoren. Wegen seiner geringen Löslichkeit im Blut flutet es schnell an und ab, sodass Einschlafen und Aufwachen rasch erfolgen. Da es die Atemwege kaum reizt, eignet es sich besonders für die Narkoseeinleitung über eine Maske, etwa bei Kindern.","nebenwirkungen":{"sehrHaeufig":["Unruhe (Agitiertheit) beim Aufwachen","Bradykardie (langsamer Puls)","Hypotonie (Blutdruckabfall)","Husten","Übelkeit, Erbrechen"],"haeufig":["Schläfrigkeit, Schwindel, Kopfschmerzen","Tachykardie (Herzrasen), Blutdruckanstieg","Atemdepression, Atemwegsverlegung, Laryngospasmus (Stimmritzenkrampf)","Vermehrter Speichelfluss","Schüttelfrost, Fieber, Unterkühlung","Veränderte Blutzucker- und Leberwerte"],"gelegentlich":["Verwirrtheit","Herzrhythmusstörungen (z. B. AV-Block, Vorhofflimmern, Extrasystolen)","Atemstillstand (Apnoe), Sauerstoffmangel","Asthma-Anfall","Harnverhalt"],"unbekannt":["Maligne Hyperthermie","Krampfanfälle, unwillkürliche Bewegungen","QT-Verlängerung mit Torsade de pointes, Herzstillstand","Anaphylaxie (schwere allergische Reaktion)","Hepatitis, Leberversagen","Hyperkaliämie (erhöhtes Kalium)","Erhöhter Hirndruck"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; beim Kaiserschnitt wurde Sevofluran sicher angewendet. Es entspannt die Gebärmuttermuskulatur, was Blutungen verstärken kann.","stillzeit":"Der Übergang in die Muttermilch ist nicht untersucht; wegen der raschen Ausscheidung ist Stillen nach dem Aufwachen meist möglich – Vorgehen mit dem Narkoseteam besprechen.","hinweise":["Nach einer Narkose mindestens 24 Stunden nicht Auto fahren, keine Maschinen bedienen und keinen Alkohol trinken.","Dem Narkoseteam maligne Hyperthermie in der Familie, Muskelerkrankungen und frühere Narkoseprobleme unbedingt melden.","Einnahme von MAO-Hemmern oder Johanniskraut vor geplanten Eingriffen angeben."],"darreichung":["Flüssigkeit zur Herstellung eines Dampfs zur Inhalation"]},"sildenafil":{"wirkmechanismus":"Verbessert die Durchblutung des Penis bei sexueller Erregung bzw. erweitert die Blutgefässe der Lunge. Sildenafil hemmt selektiv das Enzym Phosphodiesterase 5, das den Botenstoff cGMP abbaut. Bei sexueller Stimulation freigesetztes Stickstoffmonoxid (NO) erhöht cGMP in den Schwellkörpern; durch die Hemmung des Abbaus bleibt cGMP länger erhöht, die glatte Muskulatur entspannt sich und Blut strömt ein. In den Lungengefässen bewirkt derselbe Mechanismus eine Gefässerweiterung und senkt den Lungenarteriendruck.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall und Gliederschmerzen (bei Lungenhochdruck-Dosierung)"],"haeufig":["Gesichtsrötung (Flush), Hitzewallungen","Verstopfte Nase","Verdauungsbeschwerden (Dyspepsie), Übelkeit","Schwindel","Sehstörungen: veränderte Farbwahrnehmung (Blau- oder Gelbstich), verschwommenes Sehen","Nasenbluten, Schlaflosigkeit, Muskelschmerzen (bei Lungenhochdruck-Dosierung)"],"gelegentlich":["Herzrasen, Herzklopfen","Blutdruckabfall oder Blutdruckanstieg","Augenschmerzen, Lichtempfindlichkeit, gerötete Augen","Ohrensausen (Tinnitus)","Schläfrigkeit","Erbrechen, Mundtrockenheit","Hautausschlag","Blut im Urin","Brustschmerzen, Müdigkeit"],"selten":["Herzinfarkt, Herzrhythmusstörungen, plötzlicher Herztod","Schlaganfall, TIA, Krampfanfälle, Ohnmacht","NAION (Durchblutungsstörung des Sehnervs mit Sehverlust), Netzhautgefässverschluss","Plötzlicher Hörverlust","Priapismus (schmerzhafte Dauererektion über 4 Stunden)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)"]},"schwangerschaft":"Bei Lungenhochdruck nur, wenn unbedingt erforderlich – es liegen keine ausreichenden Daten vor. Für Frauen ist die Behandlung von Erektionsstörungen nicht vorgesehen.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Bei Erektionsstörungen etwa 1 Stunde vor dem Geschlechtsverkehr einnehmen; eine fettreiche Mahlzeit verzögert den Wirkungseintritt. Höchstens einmal täglich.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall – sofort ärztliche Hilfe holen.","Niemals zusammen mit Nitraten oder «Poppers» (Amylnitrit) – lebensbedrohlicher Blutdruckabfall.","Bei plötzlicher Sehverschlechterung oder plötzlichem Hörverlust sofort absetzen und ärztlich abklären lassen."],"darreichung":["Filmtabletten","Schmelztabletten","Pulver für Suspension zum Einnehmen (Revatio)"]},"silodosin":{"wirkmechanismus":"Entspannt die Muskulatur in Prostata und Blasenhals und erleichtert so das Wasserlassen. Silodosin blockiert hochselektiv die Alpha-1A-Adrenozeptoren, die vor allem in Prostata, Blasengrund, Blasenhals und Harnröhre vorkommen. Dadurch sinkt der Widerstand für den Harnabfluss, und Beschwerden wie schwacher Harnstrahl oder häufiger Harndrang nehmen ab. Die Prostata wird dabei nicht verkleinert.","nebenwirkungen":{"sehrHaeufig":["Ejakulationsstörungen (verminderter oder fehlender Samenerguss, retrograde Ejakulation)"],"haeufig":["Schwindel","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Verstopfte Nase","Durchfall"],"gelegentlich":["Verminderte Libido, Erektionsstörung","Herzrasen","Blutdruckabfall","Übelkeit, Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Synkope (Ohnmacht), Bewusstlosigkeit","Herzklopfen"],"sehrSelten":["Allergische Reaktionen mit Schwellung von Gesicht, Zunge oder Rachen"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Operationen am grauen Star"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Täglich zur gleichen Zeit mit einer Mahlzeit einnehmen.","Zu Beginn kann beim Aufstehen Schwindel auftreten – langsam aufstehen und sich bei Schwindel hinsetzen.","Vor einer Operation am grauen Star die Einnahme angeben.","Ein verminderter oder fehlender Samenerguss ist häufig und nach dem Absetzen umkehrbar."],"darreichung":["Hartkapseln"]},"simeticon":{"wirkmechanismus":"Lässt Gasbläschen im Darm zerfallen, sodass das Gas leichter abgehen oder über die Darmwand aufgenommen werden kann. Simeticon ist eine Mischung aus Dimeticon (einem Silikonöl) und Siliciumdioxid, die die Oberflächenspannung der Schaumbläschen im Speisebrei herabsetzt; kleine Bläschen vereinigen sich zu grösseren Gasblasen. Es wirkt rein physikalisch, wird nicht ins Blut aufgenommen und unverändert mit dem Stuhl ausgeschieden.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen wie Hautausschlag oder Juckreiz"]},"schwangerschaft":"Kann angewendet werden, da Simeticon nicht ins Blut aufgenommen wird.","stillzeit":"Kann in der Stillzeit angewendet werden.","hinweise":["Nach den Mahlzeiten und bei Bedarf vor dem Schlafengehen einnehmen; Kautabletten gut kauen, Tropfen vor Gebrauch schütteln.","Bei Säuglingen können die Tropfen in den Schoppen gegeben oder vor dem Stillen mit einem Löffel verabreicht werden.","Bei Verschlucken von Spülmittel zusätzlich Tox Info Suisse unter Telefon 145 anrufen."],"darreichung":["Kautabletten","Tropfen (Suspension zum Einnehmen)"]},"simvastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Simvastatin ist ein Prodrug (Lacton), das in der Leber zur aktiven Beta-Hydroxysäure umgewandelt wird; diese hemmt die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden daraufhin mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut; zusätzlich sinken die Triglyceride leicht und das HDL-Cholesterin steigt etwas. Simvastatin wird vor allem über CYP3A4 abgebaut, deshalb sind Wechselwirkungen häufig und können zu Muskelschäden führen.","nebenwirkungen":{"selten":["Myopathie, Myositis (Muskelentzündung), Muskelschmerzen und -krämpfe","Rhabdomyolyse (Muskelzerfall), teils mit akutem Nierenversagen","Verstopfung, Bauchschmerzen, Blähungen, Verdauungsbeschwerden, Durchfall, Übelkeit, Erbrechen","Kopfschmerzen, Schwindel, Parästhesien (Kribbeln), periphere Neuropathie","Erhöhte Leberwerte und CK (Muskelenzym); Hepatitis, Gelbsucht","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hautausschlag, Juckreiz, Haarausfall; Überempfindlichkeitssyndrom (u. a. Angioödem, Gelenkbeschwerden, Fieber)","Anämie (Blutarmut), Schwäche"],"sehrSelten":["Leberversagen, auch tödlich","Muskelriss","Gedächtnisstörungen, Schlaflosigkeit","Lichenoide Hautausschläge","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Tendinopathie (Sehnenschäden), teils mit Sehnenriss","Interstitielle Lungenerkrankung","Depression","Erektionsstörung","Myasthenia gravis (Muskelschwäche) oder deren Verschlechterung","Diabetes mellitus bei Personen mit Risikofaktoren"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Bei Eintritt einer Schwangerschaft sofort absetzen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Kontraindiziert – Übergang in die Muttermilch nicht bekannt, schwere Nebenwirkungen beim Säugling möglich.","hinweise":["Einmal täglich am Abend einnehmen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Grapefruitsaft meiden; neue Medikamente (v. a. Antibiotika, Pilzmittel, Herz- und HIV-Mittel) immer auf Wechselwirkungen prüfen lassen.","Leberwerte vor Behandlungsbeginn und bei Bedarf kontrollieren; Ernährung und Bewegung bleiben wichtig."],"darreichung":["Filmtabletten"]},"sitagliptin":{"wirkmechanismus":"Verstärkt die Wirkung körpereigener Darmhormone, die nach dem Essen die Insulinausschüttung anregen. Sitagliptin hemmt selektiv das Enzym Dipeptidylpeptidase-4 (DPP-4), das die Inkretine GLP-1 und GIP rasch abbaut; deren aktive Spiegel steigen dadurch auf das Zwei- bis Dreifache. Die Folge ist eine blutzuckerabhängige Steigerung der Insulinfreisetzung und eine geringere Glukagonausschüttung – bei normalem Blutzucker lässt die Wirkung nach, daher allein kaum Unterzuckerungen. Sitagliptin wird überwiegend unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung), vor allem in Kombination mit Sulfonylharnstoff oder Insulin","Kopfschmerzen","In Kombination mit Metformin: Übelkeit, Blähungen","In Kombination mit Pioglitazon: periphere Ödeme (Wassereinlagerungen)"],"gelegentlich":["Schwindel","Verstopfung","Juckreiz"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)"],"unbekannt":["Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie, Angioödem, Ausschlag, Nesselsucht und kutaner Vaskulitis","Schwere Hautreaktionen einschliesslich Stevens-Johnson-Syndrom","Bullöses Pemphigoid (blasenbildende Hauterkrankung)","Akute Pankreatitis, auch hämorrhagisch oder nekrotisierend mit tödlichem Verlauf","Interstitielle Lungenerkrankung","Gelenk-, Muskel- und Rückenschmerzen","Eingeschränkte Nierenfunktion, akutes Nierenversagen","Erbrechen"]},"schwangerschaft":"Nicht anwenden: Es liegen keine ausreichenden Erfahrungen vor; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht anwenden: Es ist nicht bekannt, ob Sitagliptin beim Menschen in die Muttermilch übergeht (bei Ratten ja).","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen, eventuell in den Rücken ausstrahlend, sofort ärztlich abklären lassen (mögliche Bauchspeicheldrüsenentzündung).","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen, da die Dosis davon abhängt.","Allein eingenommen kaum Unterzuckerungen; in Kombination mit Sulfonylharnstoff oder Insulin kann eine Unterzuckerung die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"solifenacin":{"wirkmechanismus":"Beruhigt den überaktiven Blasenmuskel, sodass die Blase mehr Urin speichern kann. Solifenacin ist ein kompetitiver, bevorzugt am M3-Subtyp wirkender Muskarinrezeptor-Antagonist; M3-Rezeptoren vermitteln die Kontraktion des Blasenmuskels (Detrusor). Der Wirkstoff hat eine lange Halbwertszeit (etwa 45–68 Stunden) und wird hauptsächlich über CYP3A4 in der Leber abgebaut.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Verschwommenes Sehen","Verstopfung","Übelkeit, Verdauungsbeschwerden, Bauchschmerzen"],"gelegentlich":["Harnwegsinfektion, Blasenentzündung","Schläfrigkeit, Geschmacksstörung","Trockene Augen, trockene Nase, trockener Hals","Reflux","Trockene Haut","Erschwertes Wasserlassen","Müdigkeit, Wassereinlagerungen in den Beinen"],"selten":["Schwindel, Kopfschmerzen","Darmverschluss durch Stuhl (Koprostase), Erbrechen","Juckreiz, Hautausschlag","Harnverhalt"],"sehrSelten":["Halluzinationen, Verwirrtheit","Erythema multiforme, Nesselsucht, Angioödem"],"unbekannt":["Anaphylaktische Reaktion","QT-Verlängerung, Torsade de pointes, Vorhofflimmern, Herzrasen","Delir","Glaukom","Darmlähmung (Ileus)","Leberfunktionsstörungen","Hyperkaliämie","Nierenfunktionsstörung","Muskelschwäche"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Erfahrungen vor; nur bei eindeutiger Notwendigkeit.","stillzeit":"Vermeiden – im Tierversuch ging Solifenacin in die Milch über.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten unzerkaut mit Flüssigkeit einnehmen.","Verschwommenes Sehen, Schläfrigkeit oder Müdigkeit können die Fahrtüchtigkeit beeinträchtigen.","Bei Schwellungen von Gesicht, Zunge oder Rachen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"somapacitan":{"wirkmechanismus":"Ersetzt fehlendes Wachstumshormon und muss dank langer Wirkdauer nur einmal pro Woche gespritzt werden. Somapacitan ist ein gentechnisch hergestelltes Wachstumshormon mit einer angehängten Seitenkette, die sich reversibel an Albumin im Blut bindet und so den Abbau verzögert. Es aktiviert den Wachstumshormon-Rezeptor, worauf vor allem in der Leber IGF-1 gebildet wird. Dies fördert bei Kindern das Längenwachstum und beeinflusst bei Erwachsenen Körperzusammensetzung, Fett- und Knochenstoffwechsel.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Gelenk- und Gliederschmerzen","Periphere Ödeme (Wassereinlagerungen)","Müdigkeit, Schwäche","Reaktionen an der Injektionsstelle","Schilddrüsenunterfunktion"],"gelegentlich":["Lipohypertrophie (Fettgewebsverdickung an der Einstichstelle)","Karpaltunnelsyndrom","Juckreiz, Nesselsucht","Gelenk- oder Muskelsteifigkeit"],"unbekannt":["Hüftkopfgleiten bei Kindern","Gutartige Hirndrucksteigerung","Bauchspeicheldrüsenentzündung","Erhöhter Blutzucker","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Einmal pro Woche am gleichen Wochentag unter die Haut spritzen; Einstichstellen wechseln.","Eine vergessene Dosis innerhalb von 3 Tagen nachholen, danach wie gewohnt weiterfahren.","Hinken, Hüft- oder Knieschmerzen sowie starke Kopfschmerzen mit Sehstörungen oder Erbrechen ärztlich abklären.","Regelmässige Kontrollen von IGF-1, Blutzucker und Schilddrüsenwerten."],"darreichung":["Injektionslösung im Fertigpen"]},"somatrogon":{"wirkmechanismus":"Ersetzt fehlendes Wachstumshormon und wird dank langer Wirkdauer nur einmal pro Woche gespritzt. Somatrogon ist ein gentechnisch hergestelltes Wachstumshormon, das mit drei Kopien eines kurzen Peptidstücks aus dem Hormon hCG (C-terminales Peptid) verbunden ist; dies verlängert die Halbwertszeit. Es aktiviert den Wachstumshormon-Rezeptor, worauf IGF-1 gebildet wird, das an den Wachstumsfugen das Längenwachstum fördert.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schmerzen, Rötung, Schwellung, Juckreiz)","Kopfschmerzen","Fieber"],"haeufig":["Schilddrüsenunterfunktion","Gelenk- und Gliederschmerzen","Anämie (Blutarmut)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Allergische Bindehautentzündung"],"unbekannt":["Nebennierenrinden-Insuffizienz","Hüftkopfgleiten (Epiphysiolysis capitis femoris)","Gutartige Hirndrucksteigerung","Bauchspeicheldrüsenentzündung","Fortschreiten einer Skoliose"]},"schwangerschaft":"Keine Daten; Anwendung nicht empfohlen.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Einmal pro Woche am gleichen Wochentag unter die Haut spritzen; Einstichstellen wechseln.","Bei Umstellung von täglichem Wachstumshormon die erste Dosis am Tag nach der letzten täglichen Injektion geben.","Eine vergessene Dosis innerhalb von 3 Tagen nachholen, danach wie gewohnt weiterfahren.","Hinken, Hüft- oder Knieschmerzen sowie starke Kopfschmerzen mit Sehstörungen ärztlich abklären; IGF-1, Blutzucker und Schilddrüse regelmässig kontrollieren."],"darreichung":["Injektionslösung im Fertigpen"]},"somatropin":{"wirkmechanismus":"Ersetzt das körpereigene Wachstumshormon der Hirnanhangdrüse und fördert bei Kindern das Längenwachstum der Knochen. Somatropin ist gentechnisch hergestellt und mit dem menschlichen Hormon identisch. Es bindet an Wachstumshormon-Rezeptoren und regt vor allem in der Leber die Bildung von IGF-1 (insulinähnlicher Wachstumsfaktor 1) an, das an den Wachstumsfugen das Knochenwachstum stimuliert. Zudem fördert es den Eiweissaufbau und den Fettabbau und wirkt dem Insulin entgegen, sodass der Blutzucker steigen kann. Bei Erwachsenen mit Mangel verbessert es Körperzusammensetzung, Knochendichte und Blutfette.","nebenwirkungen":{"sehrHaeufig":["Gelenkschmerzen (v. a. bei Erwachsenen)","Periphere Ödeme (Wassereinlagerungen, v. a. bei Erwachsenen zu Therapiebeginn)"],"haeufig":["Reaktionen an der Einstichstelle (Schmerz, Rötung, Schwellung)","Kopfschmerzen","Parästhesien (Kribbeln, Taubheitsgefühl)","Muskelschmerzen, Muskel- und Gelenksteifigkeit"],"gelegentlich":["Karpaltunnelsyndrom","Hautausschlag, Juckreiz, Nesselsucht","Gynäkomastie (Brustvergrösserung)"],"unbekannt":["Erhöhter Hirndruck (benigne intrakranielle Hypertension) mit Kopfschmerzen, Sehstörungen und Erbrechen","Epiphysiolysis capitis femoris (Abrutschen der Hüftkopf-Wachstumsfuge) bei Kindern","Insulinresistenz, Typ-2-Diabetes","Schilddrüsenunterfunktion","Verminderter Cortisolspiegel","Pankreatitis (Bauchspeicheldrüsenentzündung)","Leukämie (Einzelfälle bei Kindern, Zusammenhang unklar)"]},"schwangerschaft":"Nicht empfohlen; die Erfahrungen sind ungenügend. Tritt eine Schwangerschaft ein, ärztlich über das weitere Vorgehen entscheiden.","stillzeit":"Nur nach ärztlicher Abwägung: es ist nicht bekannt, ob Somatropin in die Muttermilch übergeht; eine Aufnahme durch das Kind ist aber unwahrscheinlich.","hinweise":["Die Einstichstelle bei jeder Injektion wechseln, um Veränderungen des Unterhautfettgewebes zu vermeiden.","Regelmässige Kontrollen von Wachstum, IGF-1, Blutzucker und Schilddrüsenwerten.","Pens und Patronen je nach Präparat im Kühlschrank lagern, nicht einfrieren.","Nicht zur Leistungssteigerung oder als Anti-Aging-Mittel verwenden: Missbrauch ist Doping und gesundheitsschädlich."],"darreichung":["Injektionslösung (Fertigpen, Patrone)","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"sotalol":{"wirkmechanismus":"Stabilisiert den Herzrhythmus und verlangsamt den Puls. Sotalol blockiert nicht-selektiv Beta-1- und Beta-2-Rezeptoren und hemmt zusätzlich Kaliumkanäle (IKr) der Herzmuskelzellen. Dadurch verlängern sich Aktionspotenzial und Refraktärzeit in Vorhöfen und Kammern (Klasse-III-Wirkung), was kreisende Erregungen unterbricht. Die dabei auftretende Verlängerung der QT-Zeit erklärt zugleich das Risiko für Torsade-de-pointes-Arrhythmien.","nebenwirkungen":{"haeufig":["Torsade de pointes und andere neue oder verstärkte Herzrhythmusstörungen","Bradykardie (langsamer Puls), Reizleitungsstörungen","Atemnot, Brustschmerzen, Herzklopfen, Ödeme","Blutdruckabfall, Ohnmacht (Synkope)","Müdigkeit, Schwindel, Kopfschmerzen, Kribbeln","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Geschmacksstörungen","Angst, Verwirrtheit, Stimmungsschwankungen, Schlafstörungen","Seh- und Hörstörungen, Hautausschlag, Muskelkrämpfe, sexuelle Funktionsstörungen"],"unbekannt":["Bronchospasmus (Verkrampfung der Atemwege)","Verschlechterung einer Herzinsuffizienz","Verdeckte Unterzuckerungszeichen bei Diabetes","Verschlechterung von Durchblutungsstörungen und Psoriasis"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach strenger ärztlicher Abwägung; beim Neugeborenen können langsamer Puls, Unterzuckerung und Atemprobleme auftreten.","stillzeit":"Sotalol reichert sich in der Muttermilch an; Stillen wird nicht empfohlen.","hinweise":["Behandlungsbeginn und Dosiserhöhungen nur unter EKG-Kontrolle (QT-Zeit); Nierenfunktion, Kalium und Magnesium regelmässig prüfen lassen.","Bei Durchfall oder Erbrechen ärztlich melden – Elektrolytverluste erhöhen das Risiko gefährlicher Rhythmusstörungen.","Vor der Einnahme neuer Medikamente, auch rezeptfreier, auf QT-Verlängerung prüfen lassen.","Vor den Mahlzeiten einnehmen und nicht abrupt absetzen."],"darreichung":["Tabletten"]},"sotatercept":{"wirkmechanismus":"Greift am krankhaften Umbau der Lungengefässe an, statt diese nur zu erweitern. Sotatercept ist ein Fusionsprotein aus dem Activin-Rezeptor Typ IIA und einem Antikörperteil; es fängt Activine und verwandte Wachstumsfaktoren ab. Dadurch wird das bei PAH gestörte Gleichgewicht zwischen wachstumsfördernden (Activin) und wachstumshemmenden (BMPR2) Signalen wiederhergestellt, die Zellvermehrung in der Gefässwand gebremst und der Widerstand in den Lungengefässen gesenkt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasenbluten","Teleangiektasien (sichtbare erweiterte Äderchen der Haut)","Durchfall","Schwindel","Erhöhtes Hämoglobin (Erythrozytose)","Thrombozytopenie (Mangel an Blutplättchen)"],"haeufig":["Zahnfleischbluten","Hautausschlag, Hautrötung","Blutdruckanstieg"],"unbekannt":["Schwere Blutungen (z. B. im Magen-Darm-Trakt oder im Kopf)"]},"schwangerschaft":"Nicht anwenden – im Tierversuch fruchtschädigend. Vor Beginn Schwangerschaftstest; zuverlässige Verhütung während und bis 4 Monate nach der letzten Dosis.","stillzeit":"Nicht stillen, während der Behandlung und bis 4 Monate nach der letzten Dosis.","hinweise":["Hämoglobin und Thrombozyten werden vor den ersten 5 Dosen und danach regelmässig kontrolliert.","Ungewöhnliche Blutungen, schwarzen Stuhl oder plötzliche starke Kopfschmerzen sofort ärztlich melden.","Wird alle 3 Wochen unter die Haut gespritzt; Selbstinjektion nach Schulung möglich."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (unter die Haut)"]},"spironolacton":{"wirkmechanismus":"Hemmt die Wirkung des Hormons Aldosteron in der Niere; dadurch werden mehr Salz und Wasser ausgeschieden, Kalium dagegen zurückgehalten. Spironolacton und seine aktiven Abbauprodukte (u. a. Canrenon) blockieren kompetitiv den Mineralokortikoid-Rezeptor im spätdistalen Tubulus und im Sammelrohr. Bei Herzinsuffizienz wirkt es zusätzlich den schädlichen Aldosteronwirkungen auf Herz und Gefässe (Umbau, Vernarbung) entgegen. Es bindet auch an Androgen- und Progesteronrezeptoren, was hormonelle Nebenwirkungen wie eine Brustvergrösserung bei Männern erklärt. Die volle harntreibende Wirkung entwickelt sich erst nach 2–3 Tagen.","nebenwirkungen":{"haeufig":["Hyperkaliämie (erhöhtes Kalium)","Gynäkomastie (Brustvergrösserung beim Mann), Brustschmerzen","Verwirrtheit, Schwindel","Übelkeit","Juckreiz, Hautausschlag","Muskelkrämpfe","Akute Nierenschädigung","Unwohlsein"],"unbekannt":["Agranulozytose, Leukopenie, Thrombozytopenie","Elektrolytstörungen wie Natriummangel","Libidoveränderungen, Menstruationsstörungen","Leberfunktionsstörungen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Pemphigoid","Haarausfall, vermehrte Körperbehaarung, Nesselsucht","Gutartige Knoten in der Brust beim Mann","Magen-Darm-Beschwerden"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: im Tierversuch führte Spironolacton zu einer Verweiblichung männlicher Nachkommen.","stillzeit":"Ein Abbauprodukt (Canrenon) geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Kalium und Nierenwerte zu Beginn, nach Dosisänderungen und danach regelmässig kontrollieren lassen.","Keine Kaliumpräparate oder kaliumhaltigen Salzersatzmittel ohne ärztliche Anordnung verwenden; Schmerzmittel wie Ibuprofen oder Diclofenac meiden.","Bei Durchfall, Erbrechen oder Fieber mit Flüssigkeitsverlust ärztlichen Rat einholen (Gefahr von Nierenversagen und Hyperkaliämie).","Mit einer Mahlzeit einnehmen."],"darreichung":["Filmtabletten"]},"sucralfat":{"wirkmechanismus":"Legt sich wie ein Schutzfilm über geschädigte Stellen der Magen- und Darmschleimhaut. Im sauren Magen bildet Sucralfat eine zähe, haftende Masse, die sich bevorzugt an die eiweissreichen Geschwürsflächen bindet und sie vor Säure, Pepsin und Gallensäuren schützt. Zusätzlich bindet es Pepsin und Gallensäuren und fördert schleimhauteigene Schutzfaktoren wie Prostaglandine, Schleim und Bicarbonat. Die Magensäure wird kaum neutralisiert; der Wirkstoff selbst wird praktisch nicht aufgenommen, kleine Mengen Aluminium jedoch schon.","nebenwirkungen":{"haeufig":["Obstipation (Verstopfung)"],"gelegentlich":["Mundtrockenheit","Übelkeit"],"selten":["Hautausschlag, Juckreiz"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Erbrechen, Völlegefühl, Blähungen","Bezoarbildung (Klumpen im Magen)","Blutzuckeranstieg bei Diabetes","Aluminiumanreicherung mit Knochenerweichung oder Hirnschädigung (Enzephalopathie) bei Niereninsuffizienz"]},"schwangerschaft":"Da praktisch nichts aufgenommen wird, ist die Anwendung nach ärztlicher Abwägung möglich; eine Langzeitanwendung meiden.","stillzeit":"Nach ärztlicher Abwägung möglich; es ist kein relevanter Übergang in die Muttermilch zu erwarten.","hinweise":["Auf nüchternen Magen einnehmen, vor den Mahlzeiten und vor dem Schlafengehen.","Andere Arzneimittel mindestens 2 Stunden vorher einnehmen.","Bei Nierenschwäche nicht ohne ärztliche Kontrolle über längere Zeit einnehmen."],"darreichung":["Tabletten","Suspension zum Einnehmen"]},"sugammadex":{"wirkmechanismus":"Hebt die Muskelerschlaffung nach einer Narkose auf, indem es das Muskelrelaxans im Blut abfängt. Sugammadex ist ein modifiziertes Gamma-Cyclodextrin, das Rocuronium und Vecuronium in seinem Ring einschliesst und einen sehr festen Komplex bildet. Dadurch sinkt die freie Menge des Relaxans an der motorischen Endplatte, und die Muskelkraft kehrt innert weniger Minuten zurück – auch nach tiefer Blockade. Der Komplex wird unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Komplikationen beim Erwachen aus der Narkose (Bewegungen, Husten, Pressen gegen den Beatmungsschlauch)","Atemwegskomplikationen während der Narkose"],"gelegentlich":["Überempfindlichkeitsreaktionen (Hautrötung, Ausschlag) bis zur Anaphylaxie","Wiederkehrende Muskelerschlaffung (Recurarisierung)"],"unbekannt":["Ausgeprägte Bradykardie (verlangsamter Puls) bis zum Herzstillstand","Bronchospasmus (Verkrampfung der Atemwege)","Blutdruckabfall während des Eingriffs"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; nur nach sorgfältiger Abwägung anwenden. Tierversuche zeigen keine schädlichen Wirkungen.","stillzeit":"Ob Sugammadex in die Muttermilch übergeht, ist nicht bekannt; da es über den Darm kaum aufgenommen wird, ist nach einer Einzeldosis keine Wirkung beim Säugling zu erwarten.","hinweise":["Frauen mit Pille, Ring, Implantat oder Hormonspirale: während 7 Tagen nach der Narkose zusätzlich mit Kondom verhüten.","Wird nur von Anästhesie-Fachpersonen angewendet; Atmung und Kreislauf werden nach der Gabe überwacht."],"darreichung":["Injektionslösung"]},"sulfamethoxazol-trimethoprim":{"wirkmechanismus":"Hemmt die Vermehrung von Bakterien, indem es ihre Folsäure-Herstellung an zwei Stellen blockiert. Sulfamethoxazol verdrängt die Para-Aminobenzoesäure und hemmt die Dihydropteroat-Synthase; Trimethoprim hemmt die bakterielle Dihydrofolat-Reduktase. Ohne Folsäure können die Bakterien keine Erbsubstanz bilden; die doppelte Blockade wirkt synergistisch und oft bakterizid. Trimethoprim hemmt in der Niere zudem Natriumkanäle, was das Kalium im Blut erhöhen kann.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium), vor allem bei hohen Dosen"],"haeufig":["Übelkeit, Durchfall","Hautausschlag","Kopfschmerzen","Pilzinfektionen (Candida)"],"gelegentlich":["Erbrechen"],"sehrSelten":["Blutbildschäden: Agranulozytose, megaloblastäre oder aplastische Anämie, Thrombozytopenie, Panzytopenie","Hämolytische Anämie (Blutzerfall), besonders bei G6PD-Mangel","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Lichtempfindlichkeit","Anaphylaxie, Angioödem, Arzneimittelfieber","Hepatitis mit Gelbsucht, Lebernekrose","Hyponatriämie (Natriummangel), Hypoglykämie (Unterzuckerung)","Aseptische Meningitis, Krampfanfälle, Halluzinationen","Interstitielle Nephritis, Nierenfunktionsstörung, Kristallurie; Pankreatitis; Lungeninfiltrate"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Schwere Lungenschädigung bis zum akuten Lungenversagen (ARDS)","Hämophagozytische Lymphohistiozytose (lebensbedrohliche Überaktivierung des Immunsystems)","Clostridioides-difficile-Kolitis"]},"schwangerschaft":"Trimethoprim ist ein Folsäure-Antagonist: im 1. Drittel nur bei zwingender Indikation (mit Folsäure-Ergänzung). Kurz vor der Geburt vermeiden, weil Sulfonamide beim Neugeborenen einen Kernikterus begünstigen können.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Abwägung; vermeiden bei Früh- oder Neugeborenen, bei Gelbsucht oder G6PD-Mangel des Kindes.","hinweise":["Reichlich trinken, um Kristalle im Urin zu vermeiden; starke Sonne meiden.","Bei Hautausschlag, Blasen, Fieber, Halsschmerzen oder Blutungszeichen sofort absetzen und ärztlichen Rat holen.","Bei längerer Einnahme Blutbild, Kalium und Nierenwerte kontrollieren lassen."],"darreichung":["Tabletten","Suspension zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung"]},"sulfasalazin":{"wirkmechanismus":"Hemmt Entzündungen im Darm und in den Gelenken. Sulfasalazin ist eine Vorstufe (Prodrug): Darmbakterien spalten es im Dickdarm in 5-Aminosalicylsäure (Mesalazin) und Sulfapyridin. Mesalazin wirkt örtlich an der Darmschleimhaut entzündungshemmend (Hemmung von Prostaglandinen und Leukotrienen, Abfangen von Sauerstoffradikalen); das ins Blut aufgenommene Sulfapyridin trägt vermutlich zur Wirkung bei Rheuma bei und verursacht den Grossteil der Nebenwirkungen. Zusätzlich dämpft Sulfasalazin die Aktivierung von Immunzellen (u. a. über NF-κB).","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Magenbeschwerden"],"haeufig":["Appetitlosigkeit, Erbrechen, Bauchschmerzen, Durchfall","Kopfschmerzen, Schwindel, Geschmacksstörungen","Ohrensausen (Tinnitus)","Husten","Juckreiz","Gelenkschmerzen","Fieber","Leukopenie (Mangel an weissen Blutkörperchen), Eiweiss im Urin"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Depression","Atemnot","Haarausfall","Nesselsucht","Erhöhte Leberwerte"],"unbekannt":["Agranulozytose, aplastische Anämie, Panzytopenie (schwere Blutbildschäden); megaloblastäre oder hämolytische Anämie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Hepatitis bis Leberversagen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenschäden (Lungeninfiltrate, fibrosierende Alveolitis)","Nierenentzündung, nephrotisches Syndrom","Herzbeutel- oder Herzmuskelentzündung","Vorübergehend verminderte Spermienzahl (Oligospermie)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden; wegen der verminderten Folsäureaufnahme wird eine zusätzliche Folsäure-Einnahme empfohlen.","stillzeit":"Sulfapyridin geht in die Muttermilch über; bei gesunden, reifen Säuglingen meist vertretbar. Vorsicht bei Frühgeborenen, Neugeborenengelbsucht oder G6PD-Mangel; blutiger Durchfall beim Säugling wurde beschrieben.","hinweise":["Blutbild, Leber- und Nierenwerte regelmässig kontrollieren lassen; bei Halsschmerzen, Fieber, Blässe oder Blutungen sofort ärztlich melden.","Urin und Haut können sich gelb-orange verfärben; weiche Kontaktlinsen können sich dauerhaft verfärben.","Tabletten nach dem Essen mit reichlich Flüssigkeit einnehmen; magensaftresistente Tabletten nicht zerkauen."],"darreichung":["Tabletten","Magensaftresistente Tabletten"]},"sumatriptan":{"wirkmechanismus":"Lindert den Migränekopfschmerz, indem es erweiterte Blutgefässe im Kopf verengt und die Freisetzung entzündlicher Botenstoffe bremst. Sumatriptan ist ein selektiver Agonist an Serotonin-5-HT1B- und -5-HT1D-Rezeptoren: Über 5-HT1B verengt es erweiterte kraniale Gefässe, über 5-HT1D hemmt es die Ausschüttung von Neuropeptiden wie CGRP aus den Endigungen des Trigeminusnervs. Es wirkt nur im Anfall, nicht vorbeugend. Der Abbau erfolgt hauptsächlich über die Monoaminoxidase A (MAO-A).","nebenwirkungen":{"haeufig":["Schwindel, Schläfrigkeit","Kribbeln oder Taubheitsgefühl (Parästhesien), Hitze- oder Kältegefühl","Vorübergehender Blutdruckanstieg, Gesichtsrötung (Flush)","Atemnot (Dyspnoe)","Übelkeit, Erbrechen","Schwere-, Druck- oder Engegefühl in Brust, Hals oder Gliedern","Müdigkeit, Schwächegefühl, Muskelschmerzen","Schmerzen, Brennen, Rötung oder Schwellung an der Einstichstelle (Injektion)"],"sehrSelten":["Leichte Veränderungen der Leberwerte"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Koronare Gefässkrämpfe, Angina pectoris, Herzinfarkt","Herzrhythmusstörungen (Herzrasen, verlangsamter Puls)","Krampfanfälle, Zittern, Bewegungsstörungen","Sehstörungen (Flimmern, Doppelbilder, vorübergehender Sehverlust)","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)","Blutdruckabfall, Raynaud-Phänomen (weisse Finger)","Durchfall"]},"schwangerschaft":"Daten aus Registern mit über 1000 Schwangerschaften zeigen kein erhöhtes Fehlbildungsrisiko; Anwendung nur nach ärztlicher Abwägung.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nach der Anwendung 12 Stunden nicht stillen (Milch abpumpen und verwerfen).","hinweise":["Erst bei Beginn des Kopfschmerzes anwenden, nicht vorbeugend während der Aura; hilft die erste Dosis nicht, bei derselben Attacke keine zweite Dosis nehmen.","Bei Brustschmerzen oder starkem Engegefühl nach der Anwendung ärztlich abklären lassen.","Akutmittel gegen Migräne an höchstens 10 Tagen pro Monat verwenden, sonst droht Kopfschmerz durch Medikamentenübergebrauch.","Kann Schläfrigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Nasenspray","Injektionslösung (Fertigspritze/Autoinjektor)"]}});
